('tcf-writing-task-1-003',null,'writing',array['task_completion','organization','grammar_accuracy','argumentation']::text[],'Identify the recipient and purpose. Include every requested practical detail, use a suitable greeting and closing, and keep the message between 60 and 120 words. Check that the reader knows what to do next.','Missed detail',false,'TCF','writing','writing','mock',array[]::text[],null,'mpk-content-v2',1200,0,null),
('tcf-writing-task-2-003',null,'writing',array['task_completion','organization','grammar_accuracy','argumentation']::text[],'Plan a brief setting, the main events, and your comments or opinion. Use concrete details and an appropriate tone for the audience. Keep the account between 120 and 150 words; do not omit the evaluative part.','Missed detail',false,'TCF','writing','writing','mock',array[]::text[],null,'mpk-content-v2',1200,0,null),
('tcf-writing-task-3-003',null,'writing',array['task_completion','organization','grammar_accuracy','argumentation']::text[],'Identify the central point in each source, compare them fairly in your own words, then give a supported personal position. Reserve space for both comparison and opinion within 120–180 words. Do not simply copy the source statements.','Missed detail',false,'TCF','writing','writing','mock',array[]::text[],null,'mpk-content-v2',1200,0,null),
('tcf-speaking-task-1-003',null,'speaking',array['interaction','task_completion','lexical_range','grammar_accuracy','pronunciation']::text[],'Answer without preparation. Give connected details about yourself, your surroundings, and your activities; respond to follow-up questions naturally. Communicate clearly within two minutes rather than reciting a memorized biography.','Missed detail',false,'TCF','speaking','speaking','mock',array[]::text[],null,'mpk-content-v2',120,0,null),
('tcf-speaking-task-2-003',null,'speaking',array['question_formation','interaction','task_completion','register','grammar_accuracy']::text[],'Use the two-minute preparation period to note question topics, not a full script. During the remaining three minutes thirty, ask relevant questions, listen, and seek clarification or alternatives. Finish by checking the information needed for your decision.','Missed detail',false,'TCF','speaking','speaking','mock',array[]::text[],null,'mpk-content-v2',330,120,null),
('tcf-speaking-task-3-003',null,'speaking',array['argumentation','organization','task_completion','lexical_range','pronunciation']::text[],'Begin immediately with a clear position. Develop two reasons and concrete examples, then add a qualification or address a counterargument. Connect your ideas and conclude within four minutes thirty. No preparation time is added.','Missed detail',false,'TCF','speaking','speaking','mock',array[]::text[],null,'mpk-content-v2',270,0,null);
